INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wei-warring','魏','["魏","梁","魏国"]',NULL,'cn','east_asia',-403,1,NULL,'year',-225,12,NULL,'month',-4824,-2677,'ochre',NULL,NULL,'三家分晋后魏氏立国，都大梁；前225年秦灭魏。与三国曹魏 wei 区分。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r1','击','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文侯之子，武侯。吴起奔楚，秦攻韩赵而未全力救，国势有损，霸业渐衰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏武侯"}]','武侯',NULL,'魏武侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r2','罃','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','惠成王，迁都大梁。桂陵、马陵惨败，又遭秦齐夹击，魏国由盛转衰，无力争霸，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏惠成王"}]','惠成王',NULL,'魏惠成王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r3','嗣','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','襄王，在位二十二年。魏国已非战国强国，无力争霸，国势转衰，割地求和，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏襄王"}]','襄王',NULL,'魏襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r4','遫','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','昭王，在位十八年。秦国屡攻魏国，割地求和，国势日衰，濒临灭亡，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏昭王"}]','昭王',NULL,'魏昭王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r5','圉','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','安僖王，在位三十三年。魏国沦为秦国附庸，割地求和，国势危急，濒临灭亡，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏安僖王"}]','安僖王',NULL,'魏安僖王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r6','午','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','景湣王，在位十四年。秦国攻魏取地，魏国奄奄一息，濒临灭亡，无力抵抗，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏景湣王"}]','景湣王',NULL,'魏景湣王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-r7','假','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','魏国末代君主。前225年秦灭魏，国亡，魏国历史终结，姬姓魏国不复存在，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/假"}]',NULL,NULL,'假','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-wen','斯','wei-warring','[]','姬','魏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','尊师重道，任用李悝、吴起改革，灭中山。魏国率先强盛，为战国初霸，国势巅峰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏文侯"}]','文侯',NULL,'魏文侯','[]');
